def compute(vars):
    collateral_2013 = vars["v1"]
    collateral_2012 = vars["v2"]
    minimum_collateral = min(collateral_2013, collateral_2012)

    return {
        "value": minimum_collateral,
        "trace": {
            "collateral_2013": collateral_2013,
            "collateral_2012": collateral_2012,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
